    private final Set<CanoeDestination> blockedCanoes = EnumSet.noneOf(CanoeDestination.class);
    private final Set<SoulWarsPortal.Entry> blockedEntryPortals = EnumSet.noneOf(SoulWarsPortal.Entry.class);
